"""The test_probe_by_code tests were split (TD-11c): the parts hold the checks and probe_by_code_common the shared helpers.
This module re-exports the names other tests import under the old name. It holds no check of its own: the canon
runs each part as its own process. `python -B test_probe_by_code.py --all` runs the parts one after the other.
"""
# split-shim: generated by tools/test_split.py
import subprocess
import sys
from pathlib import Path

sys.path.insert(0, str(Path(__file__).resolve().parent))
from probe_by_code_common import (  # noqa: E402,F401
    DISPATCH,
    FAKE_RUN_SUITE,
    OBLIGATION_REFS,
    PROVENANCE,
    PY,
    TASK,
    TEST_FILE_REL,
    _calls,
    _main_in_process,
    _streams,
    cleanup_beside,
    env_for,
    model_entries,
    mutated_line,
    project,
    read_check_record,
    read_record,
    seed_author_job,
    snapshot,
    task_of,
    tree_state,
    write_json,
)

# the re-export is the point of this module: naming it in __all__ keeps it
__all__ = ["DISPATCH", "FAKE_RUN_SUITE", "OBLIGATION_REFS", "PROVENANCE", "PY", "TASK", "TEST_FILE_REL", "_calls", "_main_in_process", "_streams", "cleanup_beside", "env_for", "model_entries", "mutated_line", "project", "read_check_record", "read_record", "seed_author_job", "snapshot", "task_of", "tree_state", "write_json"]

PARTS = ("test_probe_by_code_bindings", "test_probe_by_code_mutations", "test_probe_by_code_receipts", "test_probe_by_code_records", "test_probe_by_code_two_profiles", "test_probe_by_code_exit_order")


def main() -> int:
    if "--all" not in sys.argv[1:]:
        print("test_probe_by_code.py: no checks of its own; they are in " + ", ".join(p + ".py" for p in PARTS))
        return 0
    here = Path(__file__).resolve().parent
    code = 0
    for part in PARTS:
        code = subprocess.run([sys.executable, "-B", str(here / (part + ".py"))]).returncode or code
    return code


if __name__ == "__main__":
    sys.exit(main())
